struct Audio final:MoviePlaybackAudioOutput {
 std::shared_ptr<AudioData> data;
 explicit Audio(std::shared_ptr<AudioData> d):data(std::move(d)){}
 std::optional<mka::sound::AudioStreamFormat> format(MovieControlFailure& f)override{f={};return mka::sound::AudioStreamFormat{48000,2,3};}
 std::optional<mka::sound::AudioQueueStatus> queue_status(MovieControlFailure& f)override{f={};return mka::sound::AudioQueueStatus{2,data->padding,2-data->padding,data->submitted,data->epoch,data->started};}
 std::optional<mka::sound::AudioClockReading> clock(MovieControlFailure& f)override{f={};if(data->on_clock){auto call=std::move(data->on_clock);call();}if(data->clock_error||(data->fail_clock_after_reset&&data->resets)){f={MovieControlError::native_service,"fixture actual clock failure",72};return {};}return mka::sound::AudioClockReading{data->clock_position,123456,998877,data->epoch,true};}
 MovieAudioSubmitResult queue(std::span<const float> pcm,MovieControlFailure& f)override{f={};check(pcm.size()%2==0&&pcm.size()/2<=2-data->padding,"actual capacity respected");mka::sound::AudioSubmission r{data->submitted,pcm.size()/2,data->epoch};data->samples.insert(data->samples.end(),pcm.begin(),pcm.end());data->submitted+=r.client_frames;data->padding+=static_cast<std::uint32_t>(r.client_frames);return {MovieAudioSubmitStatus::accepted,r};}
 bool pause(bool p,MovieControlFailure& f)override{f={};data->started=!p&&data->padding>0;return true;}
 bool stop_and_reset(MovieControlFailure& f)override{f={};++data->resets;if(data->stop_error){f={MovieControlError::native_service,"fixture native cleanup failure",71};return false;}data->padding=0;data->submitted=0;data->started=false;data->clock_position=0;++data->epoch;return true;}
};
